const menu = window.ONAM_MENU;
const $ = s => document.querySelector(s);
const escapeHTML = text => String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='Favourites',limit=9,cart={};
try { const saved=JSON.parse(localStorage.getItem('onam-bag')||'{}'); for(const item of menu) if(Number.isInteger(saved[item.id])&&saved[item.id]>0&&saved[item.id]<=99)cart[item.id]=saved[item.id]; } catch {}
const favouriteIds=['snack-masala-dosa','combo-kerala-sadya-red','curry-paneer-butter'];
if($('#favourites')) $('#favourites').innerHTML=favouriteIds.map((id,index)=>{const d=menu.find(x=>x.id===id);return `<article class="food-card"><div class="food-image"><button data-detail="${d.id}" aria-label="View ${escapeHTML(d.name)}"><img src="${d.image}" alt="${escapeHTML(d.name)}" loading="lazy"></button><span class="food-tag">${['THE GOLDEN CLASSIC','A KERALA FAVOURITE','COMFORT IN A BOWL'][index]}</span></div><div class="food-info"><div class="food-title"><h3>${index===1?'Kerala Sadya':d.name}</h3><span>₹${d.price}</span></div><p>${['Crisp, golden dosa with comforting potato masala.','A banana-leaf feast, with red rice at its heart.','Soft paneer in a rich, creamy tomato gravy.'][index]}</p><div class="food-bottom"><small><span class="veg-mark">●</span> PURE VEGETARIAN</small><button class="add-button" data-add="${d.id}">Add +</button></div></div></article>`}).join('');
function renderMenu(){if(!$('#menu-grid'))return;const query=$('#menu-search').value.trim().toLowerCase();const filtered=[...menu].sort((a,b)=>Number(!!b.image)-Number(!!a.image)).filter(d=>(category==='All'||(category==='Favourites'?d.tags?.includes('Best Seller'):d.category===category))&&`${d.name} ${d.desc} ${d.tags||''}`.toLowerCase().includes(query));$('#menu-count').textContent=`${filtered.length} dishes to make your day`;$('#menu-grid').innerHTML=filtered.slice(0,limit).map(d=>`<article class="menu-item">${d.image?`<button class="menu-image-button" data-detail="${d.id}" aria-label="View ${escapeHTML(d.name)}"><img class="menu-thumb" src="${d.image}" alt="${escapeHTML(d.name)}" loading="lazy"></button>`:'<span class="no-photo" aria-hidden="true">✳</span>'}<div><button class="dish-name" data-detail="${d.id}"><h3>${escapeHTML(d.name)}</h3></button><p>${escapeHTML(d.desc)}</p><div class="food-bottom"><span class="price">₹${d.price}</span><button class="add-button" data-add="${d.id}" aria-label="Add ${escapeHTML(d.name)}">Add +</button></div></div></article>`).join('')||'<div class="empty"><h3>No dishes found.</h3><p>Try another search or choose a different category.</p><button class="button outline" id="reset-search">Show the full menu</button></div>';$('#show-more').hidden=filtered.length<=limit;}
function selectCategory(value){category=value;limit=9;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===value);b.setAttribute('aria-pressed',String(b.dataset.category===value));});renderMenu();}
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>selectCategory(b.dataset.category)));
$('#menu-search')?.addEventListener('input',()=>{limit=9;if($('#menu-search').value&&category==='Favourites')selectCategory('All');else renderMenu();});
$('#show-more')?.addEventListener('click',()=>{limit+=12;renderMenu();});
$('#drinks-link')?.addEventListener('click',()=>{selectCategory('Beverages');$('#menu-search').value='';renderMenu();$('#menu').scrollIntoView({behavior:'smooth'});});
let toastTimer;function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
function saveCart(){try{localStorage.setItem('onam-bag',JSON.stringify(cart));}catch{}$('#bag-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);}
function addDish(id){const d=menu.find(x=>x.id===id);if(!d)return;cart[id]=Math.min((cart[id]||0)+1,99);saveCart();notify(`${d.name} added to your bag`);if($('#cart-dialog').open)renderCart();}
function openDish(id){const d=menu.find(x=>x.id===id);if(!d)return;$('#dish-content').innerHTML=`${d.image?`<img src="${d.image}" alt="${escapeHTML(d.name)}">`:''}<div class="dish-body"><div class="eyebrow"><span class="veg-mark">●</span> ${d.category.toUpperCase()}</div><h2>${escapeHTML(d.name)}</h2><p>${escapeHTML(d.desc)}</p><p style="font-size:11px;margin-top:12px">Dietary requirements? Please check ingredients with the restaurant when ordering.</p><button class="button" data-add="${d.id}">Add to your order <span>₹${d.price} +</span></button></div>`;$('#dish-dialog').showModal();}
function renderCart(){const entries=menu.filter(d=>cart[d.id]);$('#cart-items').innerHTML=entries.length?entries.map(d=>`<div class="cart-row"><div><h3>${escapeHTML(d.name)}</h3><p>₹${d.price} × ${cart[d.id]}</p></div><div class="qty"><button data-qty="${d.id}" data-delta="-1" aria-label="Remove one ${escapeHTML(d.name)}">−</button><span>${cart[d.id]}</span><button data-qty="${d.id}" data-delta="1" aria-label="Add one ${escapeHTML(d.name)}">+</button></div></div>`).join(''):'<div class="empty"><h3>Good things belong here.</h3><p>Find something delicious on our menu.</p><button class="button" data-close="cart-dialog">Keep exploring ↗</button></div>';const total=entries.reduce((sum,d)=>sum+d.price*cart[d.id],0);$('#cart-summary').innerHTML=entries.length?`<div class="cart-total"><span>Estimated total</span><strong>₹${total}</strong></div><label class="cart-note">Anything we should know?<textarea id="order-note" rows="2" maxlength="500" placeholder="Pickup time, dietary requests…"></textarea></label><button class="button checkout" id="checkout">Continue on WhatsApp <span>↗</span></button><p class="cart-explain">Review and send your order in WhatsApp. The restaurant will confirm availability, final pricing and pickup or delivery details. No payment is taken here.</p>`:'';}
$('#bag-open').addEventListener('click',()=>{renderCart();$('#cart-dialog').showModal();});
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.add)addDish(b.dataset.add);if(b.dataset.detail)openDish(b.dataset.detail);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.qty){cart[b.dataset.qty]=Math.min(99,(cart[b.dataset.qty]||0)+Number(b.dataset.delta));if(cart[b.dataset.qty]<=0)delete cart[b.dataset.qty];const note=$('#order-note')?.value;saveCart();renderCart();if($('#order-note'))$('#order-note').value=note||'';}if(b.id==='reset-search'){$('#menu-search').value='';selectCategory('All');}if(b.id==='checkout'){const rows=menu.filter(d=>cart[d.id]);const total=rows.reduce((s,d)=>s+d.price*cart[d.id],0);const text=`Hello Onam Veg! I'd like to order:\n\n${rows.map(d=>`${cart[d.id]} × ${d.name} — ₹${d.price*cart[d.id]}`).join('\n')}\n\nEstimated total: ₹${total}\n${$('#order-note').value.trim()?`Note: ${$('#order-note').value.trim()}\n`:''}Please confirm availability, final price, and pickup/delivery details. Thank you!`;window.open('https://wa.me/918714703888?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#year').textContent=new Date().getFullYear();renderMenu();saveCart();

const requestedCategory=new URLSearchParams(location.search).get('category');if($('#menu-grid')&&['Combos','Rice','Curries','Breads','Snacks','Beverages','All'].includes(requestedCategory))selectCategory(requestedCategory);
